        'Log your last period to get personalized daily guidance.',
      'home.cycleToday.period.day1':
        'Day 1 of menstruation: estrogen and progesterone drop sharply, starting uterine lining shedding. Prostaglandins can cause cramps — rest, warmth, and hydration help.',
      'home.cycleToday.period.day2':
        'Day 2 of menstruation: flow is often heaviest as the endometrium sheds. Prostaglandins may peak, intensifying cramps. Low iron and fatigue are common — eat iron-rich foods and drink fluids.',
      'home.cycleToday.period.day3':
        'Day 3 of menstruation: shedding continues but flow often lightens. Hormones stay low; gentle movement and magnesium-rich foods may ease muscle tension.',
      'home.cycleToday.period.mid':
        'Day {{day}} of ~{{total}} menstruation days: the uterus is shedding its lining. Track flow and cramps — these patterns refine ovulation and next-period predictions.',
      'home.cycleToday.period.lastDay':
        'Day {{day}} of menstruation: bleeding usually tapers as shedding finishes. Estrogen begins rising — energy may improve over the next few days.',
      'home.cycleToday.follicular':
        'Cycle day {{day}} (follicular phase): estrogen rises as ovarian follicles mature. Many people feel more energy — moderate exercise and balanced meals support this phase.',
      'home.cycleToday.fertile.window':
        'Fertile window: sperm can survive ~5 days; the egg lives ~12–24 hours after ovulation. These are your highest-conception days this cycle.',
      'home.cycleToday.fertile.ovulationDay':
        'Likely ovulation day: LH surges before egg release; cervical mucus often turns clear and stretchy. Peak conception window if you are trying.',
      'home.cycleToday.luteal.mid':
        'Luteal phase: progesterone peaks then falls before bleeding. About {{days}} days until your next period — log mood and body signals.',
      'home.cycleToday.luteal.soonDays':
        'Luteal phase: progesterone drops as your period nears (about {{days}} days). Extra rest and hydration often help pre-menstrual symptoms.',
      'home.cycleToday.luteal.soon':
        'Your period may start very soon: progesterone is falling and the lining prepares to shed. Rest, hydrate, and note any familiar pre-period signs.',
