      'home.cycleToday.none': '记录上次月经以获取个性化的每日指导。',
      'home.cycleToday.period.day1':
        '经期第1天：雌激素和孕酮急剧下降，子宫内膜开始脱落。前列腺素可能引起痉挛——休息、保暖和补水有帮助。',
      'home.cycleToday.period.day2':
        '经期第2天：出血量往往最多，子宫内膜正在脱落。前列腺素可能达到峰值，加重痉挛。缺铁和疲劳较常见——多吃富铁食物并补充水分。',
      'home.cycleToday.period.day3':
        '经期第3天：脱落仍在继续，但出血量通常会减轻。激素水平仍较低；轻柔活动和富含镁的食物可能缓解肌肉紧张。',
      'home.cycleToday.period.mid':
        '经期第{{day}}天（约{{total}}天）：子宫正在脱落内膜。记录出血量和痉挛——这些模式有助于优化排卵和下次月经预测。',
      'home.cycleToday.period.lastDay':
        '经期第{{day}}天：出血通常会减少，脱落接近尾声。雌激素开始回升——接下来几天精力可能改善。',
      'home.cycleToday.follicular':
        '周期第{{day}}天（卵泡期）：随着卵巢卵泡成熟，雌激素上升。许多人感到精力增加——适度运动和均衡饮食有助于此阶段。',
      'home.cycleToday.fertile.window':
        '易孕期：精子可存活约5天，卵子排卵后约12–24小时。这是本周期受孕几率最高的日子。',
      'home.cycleToday.fertile.ovulationDay':
        '可能是排卵日：LH在卵子释放前激增；宫颈黏液常变得清澈且有弹性。若正在备孕，这是受孕高峰窗口。',
      'home.cycleToday.luteal.mid':
        '黄体期：孕酮在出血前达到峰值后下降。距下次月经约{{days}}天——记录情绪和身体信号。',
      'home.cycleToday.luteal.soonDays':
        '黄体期：随着月经临近（约{{days}}天），孕酮下降。多休息和补水往往有助于缓解经前症状。',
      'home.cycleToday.luteal.soon':
        '月经可能很快开始：孕酮正在下降，内膜准备脱落。休息、补水，并留意熟悉的经前征兆。',
